$Root = Split-Path -Parent $PSScriptRoot; $Status = Join-Path $Root 'state\latest_status.json'
while ($true) { Clear-Host; if (Test-Path $Status) { $s=Get-Content $Status -Raw|ConvertFrom-Json; Write-Progress -Activity "Whisper Research" -Status "$($s.current_experiment.id)" -PercentComplete $s.available_scope_percent; Write-Host "[$($s.available_scope_percent)% available | $($s.full_roadmap_percent)% full]"; Write-Host "GPU $($s.gpu.utilization_percent)% VRAM $($s.gpu.vram_used_mb)/$($s.gpu.vram_total_mb) MB"; if($s.last_error){Write-Host "Last: $($s.last_error)" -ForegroundColor Yellow}; $age=((Get-Date)-[datetime]$s.timestamp).TotalSeconds; if($age -gt 15){Write-Host "HEARTBEAT STALE: $([int]$age)s" -ForegroundColor Red} } else { Write-Host 'Waiting for status...' }; Start-Sleep -Seconds 4 }
